export function helpTopicFor(view, format = 'feed') {
  if (view === 'video' || view === 'create' && format === 'reels') return 'reels';
  if (view === 'create') return 'images';
  if (view === 'browser') return 'integrations';
  return Object.hasOwn(HELP_TOPICS, view) ? view : 'general';
}
